const input = items[0]?.json ?? {};

// v0.1: edit these defaults directly in this node before running.
const campaign = {
  productName: input.productName ?? 'Double-wall stainless steel bottle',
  targetCountry: input.targetCountry ?? 'Germany',
  buyerType: input.buyerType ?? 'Outdoor gear distributor',
  monthlyLeadTarget: Number(input.monthlyLeadTarget ?? 40),
  priceBand: input.priceBand ?? 'mid-market',
  productHighlights: input.productHighlights ?? [
    'OEM logo support',
    'Low MOQ',
    'Fast sample turnaround',
    'BPA-free materials'
  ],
  proofPoints: input.proofPoints ?? [
    'Existing EU export experience',
    '7-day sample turnaround',
    'Flexible packaging options'
  ],
  exclusions: input.exclusions ?? [
    'Amazon FBA aggregator',
    'Consumer-only gift shops',
    'No website or contact page'
  ]
};

return [{ json: campaign }];

const brief = items[0].json;

const market = brief.targetCountry;
const buyer = brief.buyerType;
const product = brief.productName;
const highlights = brief.productHighlights.join(', ');
const proof = brief.proofPoints.join('; ');

const searchQueries = [
  `${product} ${market} ${buyer}`,
  `${market} ${buyer} ${product} importer`,
  `${market} ${buyer} ${product} distributor`,
  `${market} ${buyer} ${product} wholesaler`,
  `${market} ${buyer} "contact"`,
  `${market} ${buyer} "about us"`,
  `${market} ${buyer} site:linkedin.com/company`,
  `${market} ${buyer} site:europages.com`,
  `${market} ${buyer} site:kompass.com`,
  `${market} ${buyer} site:yellowpages`
];

const reviewSheetColumns = [
  'row_id',
  'record_type',
  'company_name',
  'website',
  'country',
  'buyer_type',
  'contact_page',
  'linkedin_url',
  'fit_score',
  'fit_reason',
  'priority',
  'email_status',
  'first_touch_draft',
  'human_review',
  'next_action'
];

const prefixes = ['Nord', 'Alpine', 'Baltic', 'Rhein', 'Summit', 'Trail', 'Ever', 'Harbor'];
const suffixes = ['Trade', 'Supply', 'Outdoor', 'Distribution', 'Gear', 'Imports', 'Wholesale', 'Partners'];
const focusSignals = [
  'catalog shows insulated drinkware and camping accessories',
  'about page mentions wholesale distribution to retail chains',
  'product range overlaps with reusable outdoor hydration gear',
  'team profile suggests importer + distributor model',
  'website positions itself as a B2B supplier for outdoor retailers',
  'current assortment leaves room for OEM private-label bottles',
  'contact page includes buyer-oriented wholesale language',
  'product pages indicate multi-country EU fulfillment partners'
];
const scores = [5, 4, 4, 3, 5, 4, 3, 4];
const priorities = ['hot', 'hot', 'warm', 'review', 'hot', 'warm', 'review', 'warm'];

const makeSlug = (parts) => parts.join('-').replace(/[^a-zA-Z0-9-]/g, '').toLowerCase();
const demoCount = Math.min(brief.monthlyLeadTarget, 8);

const starterRows = Array.from({ length: demoCount }, (_, index) => {
  const prefix = prefixes[index % prefixes.length];
  const suffix = suffixes[index % suffixes.length];
  const slug = makeSlug([prefix, suffix, market]);
  const company = `${prefix} ${suffix} ${market} GmbH (demo)`;
  const fitReason = `${focusSignals[index % focusSignals.length]}; good fit for ${product}`;
  const firstTouchDraft = `Hi ${company.split(' ')[0]} team, I noticed your company serves ${buyer} buyers in ${market}. We manufacture ${product} with ${brief.productHighlights[0].toLowerCase()} and ${brief.productHighlights[1].toLowerCase()}. Based on your catalog, there may be a fit for a private-label or distribution conversation. Would this category be relevant for your current sourcing plan?`;

  return {
    row_id: `lead-${String(index + 1).padStart(2, '0')}`,
    record_type: 'demo_example',
    company_name: company,
    website: `https://${slug}.example`,
    country: market,
    buyer_type: buyer,
    contact_page: `https://${slug}.example/contact`,
    linkedin_url: `https://${slug}.example/linkedin`,
    fit_score: scores[index % scores.length],
    fit_reason: fitReason,
    priority: priorities[index % priorities.length],
    email_status: 'draft_ready_for_review',
    first_touch_draft: firstTouchDraft,
    human_review: 'required',
    next_action: 'replace demo data with a real company, then review message before sending'
  };
});

const fitRubric = [
  '5 = product line directly matches and website shows active distribution/import activity',
  '4 = adjacent buyer, has wholesale/distributor signals, likely fit',
  '3 = possible fit but unclear purchasing authority or product overlap',
  '2 = weak overlap or unclear business model',
  '1 = no clear fit, missing website, or clearly excluded'
];

const outreachPrompt = `You are drafting the first outbound email for a human sales rep.\n\nProduct: ${product}\nTarget market: ${market}\nBuyer type: ${buyer}\nProduct highlights: ${highlights}\nProof points: ${proof}\n\nRules:\n1. Keep it under 120 words.\n2. Mention one concrete fit reason from the target company.\n3. No fake familiarity, no spammy urgency, no exaggerated claims.\n4. End with a low-pressure CTA asking whether this category is relevant.\n5. Human review is mandatory before sending.`;

const nextSteps = [
  'Use the queries to research 20-40 candidate companies manually or via your preferred data source.',
  'Replace each demo row with a real company before sending anything.',
  'Fill the review sheet and score every company with the rubric before drafting emails.',
  'Keep sending manual in v0.1. Do not automate email delivery before message quality is validated.'
];

return [{
  json: {
    campaign: brief,
    searchQueries,
    reviewSheetColumns,
    starterRows,
    fitRubric,
    outreachPrompt,
    nextSteps,
    notes: [
      'Starter Rows now contains demo example companies so the workflow output is visible immediately.',
      'All demo websites use the .example domain and must be replaced with real prospects before use.',
      'This MVP intentionally stops before scraping or sending email.',
      'Human review stays in the loop.'
    ]
  }
}];

const pack = items[0].json;
const campaign = pack.campaign;
return [{
  json: {
    productName: campaign.productName,
    targetCountry: campaign.targetCountry,
    buyerType: campaign.buyerType,
    monthlyLeadTarget: campaign.monthlyLeadTarget,
    searchQueriesCount: pack.searchQueries.length,
    starterRowsCount: pack.starterRows.length,
    reviewColumns: pack.reviewSheetColumns.join(' | '),
    fitRubric: pack.fitRubric.join('\n'),
    nextSteps: pack.nextSteps.join('\n'),
    notes: pack.notes.join('\n'),
    outreachPrompt: pack.outreachPrompt
  }
}];

const pack = items[0].json;
return pack.searchQueries.map((query, index) => ({
  json: {
    rank: index + 1,
    query
  }
}));
